import{z as s,x as o,o as t,c as A,q as p,j as r,D as l,d as i,s as u,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"自然率假说","description":"","frontmatter":{"title":"自然率假说","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/natural-rate-u-star.md","filePath":"econ/natural-rate-u-star.md","lastUpdated":1791063341000}'),B={name:"econ/natural-rate-u-star.md"};function d(C,a,m,h,D,F){const E=o("Mermaid");return t(),A("div",null,[a[2]||(a[2]=p('<h1 id="自然率假说" tabindex="-1">自然率假说 <a class="header-anchor" href="#自然率假说" aria-label="Permalink to &quot;自然率假说&quot;">​</a></h1><div class="epigraph"><p>把失业钉在自然率之下，必须让通胀持续跑赢预期；于是通胀加速，而不是沿着一条稳定的替换菜单滑动。</p><footer>—— Friedman, The Role of Monetary Policy, AER 1968；Phelps 同期的自然率与预期工资设定</footer></div><p><a href="/econ/phillips-expectations">上一课</a>已经把 Phillips 的统计替换写成 \\(\\pi=\\pi^e+\\kappa(u-u^*)+\\varepsilon\\)，并指出长期垂直。本课的缺口不是再画那条短曲线的形状，而是把 Friedman–Phelps 的<strong>假说</strong>写成可证伪的加速主义：自然率 \\(u^*\\) 是通胀既不加速也不减速的锚，货币不能买到永久的 \\(u\\lt u^*\\)。失业课给过 \\(u^*\\) 的定义；这里把它接到预期菲利普斯的政策含义。IS–LM 下一课才写需求侧会计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>附加预期的菲利普斯一旦写下，政策菜单立刻消失——若公众的 \\(\\pi^e\\) 跟着政策走。自然率假说把这句话提升为对货币角色的限制：名义需求可以暂时推动 \\(\\tilde{u}\\)，不能把 \\(u^*\\) 本身当作货币政策的目标函数去钉死。缺口是加速主义机制，而不是把 <a href="/econ/natural-unemployment">失业与自然率</a> 的摩擦分解再讲一遍，也不是把 \\(\\kappa\\) 的 Calvo 微观提前搬来。</p><p>Friedman（1968）：\\(u^*\\) 由劳动市场实物与制度决定；试图用通胀换失业，只会加快 \\(\\pi\\)。Phelps 从另一条工资设定走到同类结论。两者合称自然率假说，针对的是 1960 年代把 Phillips 当菜单的政策观。</p><p><span class="marginnote">术语翻译：自然率不是「理想失业率」，而是「通胀既不加速也不减速时的失业率」——一个由劳动市场摩擦、失业保险的慷慨程度、匹配效率决定的实物锚。它可以太高、可以无效率，只是货币管不了它。</span></p><p><span class="marginnote">加速主义：维持 \\(u\\lt u^*\\) 要求 \\(\\pi\\gt \\pi^e\\) 每一期都成立，于是 \\(\\pi\\) 本身上升。NAIRU 是操作近似；假说的理论对象是 \\(u^*\\)，不是某一个滤波值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把上一课的式子对时间差分（适应性预期下 \\(\\Delta\\pi^e\\) 跟 \\(\\pi\\) 走）得到：\\(\\Delta\\pi\\) 与 \\((u-u^*)\\) 同号。要把失业保持在自然率以下，必须接受<strong>加速的</strong>通胀，而不是一个更高但稳定的 \\(\\pi\\)。理性预期下，被完全预见的扩张甚至买不到暂时的 \\(\\tilde{u}\\)，只剩下立刻更高的 \\(\\pi\\)——卢卡斯把假说推到「只有意外才有实量效应」。</p><p><span class="marginnote">数字实例：想把失业压在 \\(u^\\*\\) 之下 1 个百分点（\\(\\kappa=0.5\\)），第一年要通胀超预期 0.5 个点；预期追平后，第二年还得再超 0.5 个点——通胀从 2% 爬到 2.5%、3%……一路加速，永远差着半步。</span></p>',11)),(t(),r(n,null,{default:l(()=>[u(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E9%99%84%E5%8A%A0%E9%A2%84%E6%9C%9F%E7%9A%84%20Phillips%22%5D%20--%3E%20ACC%5B%22%E5%8A%A0%E9%80%9F%E4%B8%BB%E4%B9%89%EF%BC%9Au%EF%BC%9Cu*%20%E2%87%92%20%CF%80%20%E5%8A%A0%E9%80%9F%22%5D%0A%20%20HYP%5B%22%E8%87%AA%E7%84%B6%E7%8E%87%E5%81%87%E8%AF%B4%22%5D%20--%3E%20ACC%0A%20%20HYP%20--%3E%20NEUT%5B%22%E8%B4%A7%E5%B8%81%E5%AE%9A%20%CF%80%20%E8%B6%8B%E5%8A%BF%EF%BC%8C%E4%B8%8D%E5%AE%9A%20u*%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"假说不要求 \\(u^*\\) 恒定。人口、失业保险、匹配技术会慢移 \\(u^*\\)。它要求的是：这些移动来自实物与制度，不是靠多印一张票子就能反向钉住。把 1970 年代滞胀读成「曲线坏了」，不如读成「菜单假说被加速主义拒绝」。",-1)),a[4]||(a[4]=e("h3",{id:"与自然率定义课的分工",tabindex:"-1"},[i("与自然率定义课的分工 "),e("a",{class:"header-anchor",href:"#与自然率定义课的分工","aria-label":'Permalink to "与自然率定义课的分工"'},"​")],-1)),a[5]||(a[5]=e("p",null,"定义课钉 \\(u^*\\) 为正、货币长期中性、参与率对照。本课钉政策含义：不以 \\(u\\) 为名义工具的长期目标，而以通胀（或名义锚）为长期目标，\\(u\\) 回到当时的 \\(u^*\\)。Okun 仍只把 \\(\\tilde{u}\\) 接到 \\(\\tilde{y}\\)，不提供可以永久压低的 \\(u^*\\)。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"意外扩张改变被感知的相对价格或实际工资，就业暂时上升。预期追上后，同一条短菲利普斯上移，\\(\\pi\\) 停在更高处才能维持原来的 \\(u\\)——若还想保持 \\(u\\lt u^*\\)，就必须再加速。这就是假说的拒绝域：若存在稳定的、可用名义政策维持的 \\(u\\)–\\(\\pi\\) 替换，假说失败。1970 年代高 \\(\\pi\\) 与高 \\(u\\) 并存，是对稳定负斜率菜单的拒绝，不是对短期替换的否认。",-1)),(t(),r(n,null,{default:l(()=>[u(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E6%94%BF%E7%AD%96%E6%8A%8A%20u%20%E5%8E%8B%E5%9C%A8%20u*%20%E4%B9%8B%E4%B8%8B%22%5D%20--%3E%20SURP%5B%22%E9%80%9A%E8%83%80%E8%B7%91%E8%B5%A2%E9%A2%84%E6%9C%9F%22%5D%0A%20%20SURP%20--%3E%20UDOWN%5B%22%E5%B0%B1%E4%B8%9A%E6%9A%82%E6%97%B6%E4%B8%8A%E5%8D%87%2C%20u%20%E6%9A%82%E4%BD%8E%E4%BA%8E%20u*%22%5D%0A%20%20UDOWN%20--%3E%20ADJ%5B%22%E5%85%AC%E4%BC%97%E4%B8%8A%E8%B0%83%20%CF%80e%2C%20%E8%BF%BD%E4%B8%8A%20%CF%80%22%5D%0A%20%20ADJ%20--%3E%20SHIFT%5B%22%E7%9F%AD%E8%8F%B2%E5%88%A9%E6%99%AE%E6%96%AF%E6%9B%B2%E7%BA%BF%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20SHIFT%20--%3E%20SAMEU%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20u%20%E9%9C%80%E8%A6%81%E6%9B%B4%E9%AB%98%E7%9A%84%20%CF%80%22%5D%0A%20%20SAMEU%20--%3E%7C%22%E8%BF%98%E6%83%B3%E5%8E%8B%E4%BD%8F%20u%22%7C%20TRY%0A%20%20SAMEU%20--%3E%7C%22%E6%94%BE%E5%BC%83%22%7C%20BACK%5B%22u%20%E5%9B%9E%E5%88%B0%20u*%2C%20%CF%80%20%E7%95%99%E5%9C%A8%E6%9B%B4%E9%AB%98%E5%A4%84%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=p('<p><span class="marginnote">直觉类比：把失业压在自然率之下像在跑步机上追终点——意外通胀是第一脚快跑，公众预期是慢慢加速的传送带；传送带一旦跟上，想停在原地（同一个 \\(u\\)）就得越跑越快。跳下跑步机，失业回 \\(u^\\*\\)，通胀却留在高位。</span></p><p>长期垂直于 \\(u^*\\)：预期正确时 \\(\\pi\\) 由名义锚决定。费雪方程把这个 \\(\\pi\\) 趋势送进 \\(i\\)。铸币税仍可在高通胀稳态抽取实际余额，但抽不到永久低失业——假说把两种「用通胀换东西」分开。</p><p>失业课与本课的分工再钉一次：前者给 \\(u^*\\) 的劳动力定义与 \\(y^*\\)；后者给「不能用名义工具永久压低 \\(u^*\\)」的加速主义。菲利普斯课给了方程形状；假说给的是政策拒绝域。Okun 仍然只连接 \\(\\tilde{y}\\) 与 \\(\\tilde{u}\\)，不提供可钉住的长期菜单。</p><p>若 \\(u^*\\) 因制度上升，观察到的高失业可以与稳定通胀并存，并不推翻假说——那是锚在移动，不是菜单复活。把一切高失业写成「需求不足所以假说失败」，会把结构错配当成周期性 \\(\\tilde{u}\\)。</p><p><span class="marginnote">自然率可以无效率（搜寻外部性、垄断）。假说不把它写成社会最优，只写成货币长期中性的锚。改善 \\(u^*\\) 要改劳动与产品市场，不是改 \\(M\\) 的水平。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 NAIRU，不把新凯恩斯 NKPC 的斜率当假说的检验。假说允许短期非中性，与粘性价格、不完全信息兼容。开放程度、锚定会改短期 \\(\\kappa\\)，不能把某十年美国斜率抄成假说的「系数」。也不要把 \\(u^*\\) 写成限价簿上的自然成交率。</p><p>参与率课已经说明 \\(u\\) 会漏掉退出者：假说的对象是劳动力内部的 \\(u^*\\)，不是就业人口比。把参与趋势当成可以靠通胀压回去的缺口，同样违反假说。卢卡斯批判后课会警告：政策规则一变，连估计出来的 NAIRU 都会挪——那是简化式，不是假说本身要求 \\(u^*\\) 可精确观测。</p><p>短期非中性与假说兼容：意外通胀可以暂时压低 \\(u\\)。假说拒绝的是把这条短替换当成可以钉住的长期菜单。新凯恩斯粘性给出短替换的微观，长期仍垂直于自然产出——与本课同一句，只是装置从工资误读换成交错调价。</p><p>后课默认：长期宏观把 \\(u\\to u^*\\)、\\(\\pi\\) 由名义锚决定当成假说，而不是把 Phillips 当菜单。下一课用 IS–LM 把需求侧写成计划 \\(I\\) 与计划 \\(S\\) 的会计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自然率假说：货币不能永久把 \\(u\\) 钉在 \\(u^*\\) 之下。</li><li>加速主义：维持 \\(u\\lt u^*\\) 要求通胀持续超过预期。</li><li>假说不要求 \\(u^*\\) 不变，只要求其变动来自实物与制度。</li><li>短期替换可以存在；稳定的通胀–失业菜单被拒绝。</li><li>改善 \\(u^*\\) 要改劳动与产品市场，不是改 \\(M\\) 的水平。</li><li>出处：Friedman, AER 1968；Phelps 的自然率与预期工资设定。</li></ul>',12))])}const c=s(B,[["render",d]]);export{f as __pageData,c as default};
